import{H as e,V as t,et as n,j as r}from"./chunks/framework.c0x6U8zS.js";var i=JSON.parse(`{"title":"SPF 数据包格式","description":"","frontmatter":{},"headers":[],"relativePath":"common/spf-packet.md","filePath":"common/spf-packet.md","lastUpdated":1787031321000}`),a={name:`common/spf-packet.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="spf-数据包格式" tabindex="-1">SPF 数据包格式 <a class="header-anchor" href="#spf-数据包格式" aria-label="Permalink to “SPF 数据包格式”">​</a></h1><p>本文定义 <strong>SPF</strong>（Serial Packet Format）的<strong>通用帧封装</strong>：帧头、长度、CMD、OP、VALUE、异或校验、组帧与解析。四款产品主板与网关之间的 UART 都走这套格式。</p><p><strong>CMD 取值、VALUE 含义、谁先发谁后回</strong> 不在本文。AHE01 主板命令字典见 <a href="/ahs-docs-page/products/ahe01/spf-protocol.html">STM32 ↔ ESP32 串口协议</a>。其它型号各自补充。</p><p>APP ↔ 设备空中包见 <a href="./ble-packet.html">BLE 数据包格式</a>。SPF 与 BLE 是两套独立封装，不要混用字段名。</p><h2 id="设备架构-四款相同" tabindex="-1">设备架构（四款相同） <a class="header-anchor" href="#设备架构-四款相同" aria-label="Permalink to “设备架构（四款相同）”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>APP  ←—— BLE ——→  ESP32 网关  ←—— UART（SPF）——→  STM32 主板</span></span></code></pre></div><p>ESP32 把 BLE 完整包转成 SPF 发给主板；主板处理后再用 SPF 应答或主动通知，由网关转回 BLE。</p><h2 id="_1-协议概述" tabindex="-1">1. 协议概述 <a class="header-anchor" href="#_1-协议概述" aria-label="Permalink to “1. 协议概述”">​</a></h2><p>SPF 是面向 UART 的<strong>完整帧协议</strong>，一帧即一条完整命令，不在 SPF 层再分包。超长 VALUE 由业务自己拆多帧（例如睡眠报告多条 NOTIFY）。</p><p>物理层约定（AHE01 主板 USART1，其它型号同构）：</p><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>项目</th><th>取值</th></tr></thead><tbody><tr><td>波特率</td><td>115200</td></tr><tr><td>数据位</td><td>8</td></tr><tr><td>校验</td><td>无</td></tr><tr><td>停止位</td><td>1</td></tr><tr><td>流控</td><td>无</td></tr></tbody></table></div><h2 id="_2-帧格式" tabindex="-1">2. 帧格式 <a class="header-anchor" href="#_2-帧格式" aria-label="Permalink to “2. 帧格式”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌────────┬────────┬─────────┬──────┬──────┬────────────┬───────┐</span></span>
<span class="line"><span>│ HEAD1  │ HEAD2  │ LENGTH  │ CMD  │ OP   │ VALUE      │ CHECK │</span></span>
<span class="line"><span>│ 1 字节 │ 1 字节 │ 2 字节  │ 1字节 │ 1字节 │ n 字节     │ 1 字节 │</span></span>
<span class="line"><span>└────────┴────────┴─────────┴──────┴──────┴────────────┴───────┘</span></span></code></pre></div><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>字段</th><th>长度</th><th>说明</th></tr></thead><tbody><tr><td>HEAD1</td><td>1 字节</td><td>固定 <code>0x5A</code></td></tr><tr><td>HEAD2</td><td>1 字节</td><td>固定 <code>0xA5</code></td></tr><tr><td>LENGTH</td><td>2 字节</td><td><strong>大端</strong>。等于 <code>CMD + OP + VALUE + CHECK</code> 的字节数，即 <code>3 + n</code></td></tr><tr><td>CMD</td><td>1 字节</td><td>命令码，由各链路自己定义</td></tr><tr><td>OP</td><td>1 字节</td><td>操作码，见第 4 节</td></tr><tr><td>VALUE</td><td>n 字节</td><td>负载；<code>n = LENGTH − 3</code>，可为 0</td></tr><tr><td>CHECK</td><td>1 字节</td><td>异或校验，见第 5 节</td></tr></tbody></table></div><p>关系：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>LENGTH     = 3 + value_len</span></span>
<span class="line"><span>总帧长     = LENGTH + 4  = value_len + 7</span></span>
<span class="line"><span>最短帧     = 7 字节（VALUE 为空）</span></span>
<span class="line"><span>最大帧     = 1024 字节（解析器上限）</span></span></code></pre></div><p>LENGTH 非法（小于 3，或 <code>LENGTH + 4</code> 超过 1024）时整帧丢弃。</p><h2 id="_3-字节序" tabindex="-1">3. 字节序 <a class="header-anchor" href="#_3-字节序" aria-label="Permalink to “3. 字节序”">​</a></h2><ul><li><strong>LENGTH</strong>：大端（高字节在前）。例如 VALUE 4 字节 → LENGTH = 7 → 空中为 <code>00 07</code>。</li><li><strong>VALUE 内多字节字段</strong>：业务层同样按大端，见各 CMD 文档。</li></ul><h2 id="_4-操作码-op" tabindex="-1">4. 操作码（OP） <a class="header-anchor" href="#_4-操作码-op" aria-label="Permalink to “4. 操作码（OP）”">​</a></h2><p><code>CMD</code> 表示「做什么」，<code>OP</code> 表示「读 / 写 / 应答 / 通知」。数字可能和 BLE 的 <code>cmd_type</code> 看起来像，<strong>含义不同，取值也不同</strong>。</p><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>OP</th><th>名称</th><th>方向（相对发起方）</th><th>成对关系</th></tr></thead><tbody><tr><td><code>0x00</code></td><td>写</td><td>发起方 → 对端</td><td>等 <code>0x01</code> 写应答</td></tr><tr><td><code>0x01</code></td><td>写应答</td><td>对端 → 发起方</td><td>对应刚才的写</td></tr><tr><td><code>0x02</code></td><td>读</td><td>发起方 → 对端</td><td>等 <code>0x03</code> 读应答</td></tr><tr><td><code>0x03</code></td><td>读应答</td><td>对端 → 发起方</td><td>对应刚才的读</td></tr><tr><td><code>0xFF</code></td><td>通知</td><td>对端主动上报</td><td>单向，不必先发读</td></tr></tbody></table></div><p>与 BLE <code>cmd_type</code> 的对应（仅便于对照，传输时各走各的封装）：</p><div class="vp-table-wrap"><table tabindex="0"><thead><tr><th>SPF OP</th><th>BLE cmd_type</th></tr></thead><tbody><tr><td>写 <code>0x00</code></td><td>APP 写 <code>0x02</code></td></tr><tr><td>写应答 <code>0x01</code></td><td>设备写应答 <code>0x12</code></td></tr><tr><td>读 <code>0x02</code></td><td>APP 读 <code>0x01</code></td></tr><tr><td>读应答 <code>0x03</code></td><td>设备读应答 <code>0x11</code></td></tr><tr><td>通知 <code>0xFF</code></td><td>设备主动通知 <code>0x13</code></td></tr></tbody></table></div><p>写应答 VALUE 若无特殊说明：<strong><code>0x01</code> 成功，<code>0x00</code> 失败</strong>。个别 CMD 会带附加字节或其它状态码，见该链路的命令文档。</p><h2 id="_5-异或校验-check" tabindex="-1">5. 异或校验（CHECK） <a class="header-anchor" href="#_5-异或校验-check" aria-label="Permalink to “5. 异或校验（CHECK）”">​</a></h2><p>对 <strong>HEAD1 到 VALUE 末字节</strong>（不含 CHECK 自身）按顺序异或：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CHECK = HEAD1 ⊕ HEAD2 ⊕ LENGTH_H ⊕ LENGTH_L ⊕ CMD ⊕ OP ⊕ VALUE[0] ⊕ … ⊕ VALUE[n-1]</span></span></code></pre></div><p>VALUE 为空时，异或范围停在 OP。</p><p>发送方必须计算并带上。接收方校验失败则丢弃该帧，不回调、不应答。</p><h2 id="_6-组帧" tabindex="-1">6. 组帧 <a class="header-anchor" href="#_6-组帧" aria-label="Permalink to “6. 组帧”">​</a></h2><p>发送侧按字段顺序写入缓冲区，最后填 CHECK：</p><ol><li>写入 <code>0x5A 0xA5</code></li><li>写入 LENGTH（<code>value_len + 3</code>，大端）</li><li>写入 CMD、OP</li><li>若 <code>value_len &gt; 0</code>，拷贝 VALUE</li><li>对前 <code>value_len + 6</code> 字节做异或，写入最后 1 字节</li><li>通过 UART 发出 <code>value_len + 7</code> 字节</li></ol><p>主板发送实现里 VALUE 建议不超过 <strong>512</strong> 字节（发送缓冲限制）；解析侧单帧不超过 <strong>1024</strong> 字节。</p><h2 id="_7-解析" tabindex="-1">7. 解析 <a class="header-anchor" href="#_7-解析" aria-label="Permalink to “7. 解析”">​</a></h2><p>接收侧按字节走状态机，支持<strong>粘包</strong>（同一批 UART 数据里多帧连续出现）：</p><ol><li>找 HEAD1 <code>0x5A</code>，再跟 HEAD2 <code>0xA5</code>。若第二字节又是 <code>0x5A</code>，当作新的帧头起点。</li><li>再读 2 字节 LENGTH，检查范围。</li><li>继续读满 <code>LENGTH</code> 字节（含 CMD、OP、VALUE、CHECK）。</li><li>计算异或，与 CHECK 比较；失败则复位，继续在后续字节里找下一帧头。</li><li>成功则回调完整帧，<strong>立刻复位</strong>，以便解析同批剩余数据。</li></ol><p>半帧超时：一帧未收齐时，若超过约定时间没有新字节，丢弃半帧并回到找帧头。AHE01 主板当前超时 <strong>5000 ms</strong>。</p><p>回调约束：VALUE 指向解析器内部缓冲。回调返回后下一帧会覆盖该缓冲。必须在回调里<strong>同步读完或拷贝</strong> VALUE，不要把指针存到队列里异步用。</p><h2 id="_8-通讯示例" tabindex="-1">8. 通讯示例 <a class="header-anchor" href="#_8-通讯示例" aria-label="Permalink to “8. 通讯示例”">​</a></h2><p>以下只演示封装。CMD <code>0xA1</code> 在 AHE01 上表示加热，完整含义见 <a href="/ahs-docs-page/products/ahe01/spf-protocol.html">AHE01 STM32 ↔ ESP32 串口协议</a>。</p><h3 id="_8-1-写-写应答-有-value" tabindex="-1">8.1 写 + 写应答（有 VALUE） <a class="header-anchor" href="#_8-1-写-写应答-有-value" aria-label="Permalink to “8.1 写 + 写应答（有 VALUE）”">​</a></h3><p>ESP32 写加热：开、30 分钟、中档。VALUE = <code>01 00 1E 02</code>（4 字节）。</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>LENGTH = 3 + 4 = 0x0007</span></span>
<span class="line"><span>CHECK  = 0x5A ⊕ 0xA5 ⊕ 0x00 ⊕ 0x07 ⊕ 0xA1 ⊕ 0x00 ⊕ 0x01 ⊕ 0x00 ⊕ 0x1E ⊕ 0x02 = 0x44</span></span></code></pre></div><p>发出：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>5A A5 00 07 A1 00 01 00 1E 02 44</span></span></code></pre></div><p>主板写应答成功（VALUE <code>0x01</code>）：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>LENGTH = 3 + 1 = 0x0004</span></span>
<span class="line"><span>CHECK  = 0x5A ⊕ 0xA5 ⊕ 0x00 ⊕ 0x04 ⊕ 0xA1 ⊕ 0x01 ⊕ 0x01 = 0x5A</span></span>
<span class="line"><span></span></span>
<span class="line"><span>5A A5 00 04 A1 01 01 5A</span></span></code></pre></div><h3 id="_8-2-读-读应答-读命令无-value" tabindex="-1">8.2 读 + 读应答（读命令无 VALUE） <a class="header-anchor" href="#_8-2-读-读应答-读命令无-value" aria-label="Permalink to “8.2 读 + 读应答（读命令无 VALUE）”">​</a></h3><p>读加热（VALUE 为空）：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>LENGTH = 3 + 0 = 0x0003</span></span>
<span class="line"><span>CHECK  = 0x5A ⊕ 0xA5 ⊕ 0x00 ⊕ 0x03 ⊕ 0xA1 ⊕ 0x02 = 0x5F</span></span>
<span class="line"><span></span></span>
<span class="line"><span>5A A5 00 03 A1 02 5F</span></span></code></pre></div><p>读应答 VALUE 4 字节，LENGTH = <code>0x0007</code>，OP = <code>0x03</code>。</p><h3 id="_8-3-通知-无先发读" tabindex="-1">8.3 通知（无先发读） <a class="header-anchor" href="#_8-3-通知-无先发读" aria-label="Permalink to “8.3 通知（无先发读）”">​</a></h3><p>主板周期性上报实时数据：CMD 用业务码，OP = <code>0xFF</code>，VALUE 为上报负载。网关收到后转成 BLE 通知，不必先给主板发读。</p><h2 id="_9-发送-接收流程" tabindex="-1">9. 发送 / 接收流程 <a class="header-anchor" href="#_9-发送-接收流程" aria-label="Permalink to “9. 发送 / 接收流程”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>业务层：CMD + OP + VALUE</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>    组 SPF 完整帧（含 LENGTH、CHECK）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>    UART 发出整帧</span></span></code></pre></div><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>UART 收到字节</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>    状态机找帧头 → 收齐 LENGTH → 校验 CHECK</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>    回调 CMD / OP / VALUE</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>    立刻复位，继续解析粘包</span></span></code></pre></div><h2 id="_10-重要说明" tabindex="-1">10. 重要说明 <a class="header-anchor" href="#_10-重要说明" aria-label="Permalink to “10. 重要说明”">​</a></h2><ol><li>SPF <strong>一帧一条命令</strong>，没有 BLE 那种 <code>package_num</code> / <code>package_seq</code>。</li><li>LENGTH 含 CMD、OP、VALUE、CHECK，<strong>不含</strong>两字节帧头；不要按「VALUE 长度」去填 LENGTH。</li><li>必须校验 CHECK；校验失败丢帧，不要当业务错误去回写应答。</li><li>多字节一律大端。</li><li>写之后等写应答、读之后等读应答；通知单向。超时由业务约定（主板半帧解析超时 5 秒，不等于业务应答超时）。</li><li>具体 CMD 表见对应链路文档，不要把 BLE 的 <code>cmd</code> 直接填进 SPF 的 CMD。</li></ol>`,59)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};